package io.github.turbopro.ism.bootstrap;
import com.fasterxml.jackson.databind.JsonNode;
import io.github.turbopro.ism.common.infrastructure.tenant.TenantContext;
import io.github.turbopro.ism.iam.access.AccessModels;
import org.junit.jupiter.api.Test;
import org.springframework.http.*;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
class TenantDictionaryIT extends SiteProjectSupport {
 JsonNode ok(ResponseEntity<JsonNode> r){assertThat(r.getStatusCode()).as("%s",r.getBody()).isEqualTo(HttpStatus.OK);return r.getBody().path("data");}
 String path(String type){return "/api/configuration/dictionaries/"+type;}
 JsonNode get(String token,String type){return ok(request("GET",path(type),token,null,null));}
 JsonNode entry(JsonNode type,String code){for(var item:type.path("items"))if(item.path("code").asText().equals(code))return item;return null;}
 Map<String,Object> body(String code,String label,String value,int version){return Map.of("code",code,"label",label,"value",value,"sortOrder",25,"status","ACTIVE","version",version);}
 JsonNode put(String token,String type,String code,String label,String value,int version){return ok(request("PUT",path(type)+"/items/"+code,token,UUID.randomUUID().toString(),body(code,label,value,version)));}
 JsonNode name(String token,String type,String name,int version){return ok(request("PUT",path(type)+"/name",token,UUID.randomUUID().toString(),Map.of("name",name,"version",version)));}
 @Test void nameAndItemOverridesRestoreWithoutAffectingOtherTenant(){var a=fixture();var b=fixture();String ta=tenantLogin(a,"pref-admin"),tb=tenantLogin(b,"pref-admin");assertThat(get(ta,"COMMON_STATUS").path("name").asText()).isEqualTo("通用状态");assertThat(name(ta,"COMMON_STATUS","厂内状态",0).path("nameVersion").asInt()).isOne();assertThat(get(tb,"COMMON_STATUS").path("name").asText()).isEqualTo("通用状态");assertThat(entry(put(ta,"COMMON_STATUS","ACTIVE","可用","ACTIVE",0),"ACTIVE").path("source").asText()).isEqualTo("TENANT_OVERRIDE");assertThat(entry(get(tb,"COMMON_STATUS"),"ACTIVE").path("label").asText()).isEqualTo("启用");ok(request("DELETE",path("COMMON_STATUS")+"/items/ACTIVE?version=1",ta,UUID.randomUUID().toString(),null));var restored=entry(get(ta,"COMMON_STATUS"),"ACTIVE");assertThat(restored.path("source").asText()).isEqualTo("SYSTEM");assertThat(restored.path("version").asInt()).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT JSON_UNQUOTE(JSON_EXTRACT(after_summary,'$.entry.label')) FROM sys_audit_event WHERE tenant_id=? AND action='DICTIONARY_ITEM_UPSERT'",String.class,a.tenant())).isEqualTo("可用");assertThat(jdbc.queryForObject("SELECT JSON_UNQUOTE(JSON_EXTRACT(after_summary,'$.entry.source')) FROM sys_audit_event WHERE tenant_id=? AND action='DICTIONARY_ITEM_DELETE'",String.class,a.tenant())).isEqualTo("SYSTEM");ok(request("DELETE",path("COMMON_STATUS")+"/name?version=1",ta,UUID.randomUUID().toString(),null));var base=get(ta,"COMMON_STATUS");assertThat(base.path("name").asText()).isEqualTo("通用状态");assertThat(base.path("nameVersion").asInt()).isEqualTo(2);}
 @Test void itemAndNameRevisionsNeverResetAcrossRestoration(){var f=fixture();String t=tenantLogin(f,"pref-admin");put(t,"COMMON_STATUS","ACTIVE","第一版","ACTIVE",0);ok(request("DELETE",path("COMMON_STATUS")+"/items/ACTIVE?version=1",t,"restore-"+f.tenant(),null));assertThat(request("PUT",path("COMMON_STATUS")+"/items/ACTIVE",t,"stale-"+f.tenant(),body("ACTIVE","旧版本覆盖","ACTIVE",0)).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(entry(put(t,"COMMON_STATUS","ACTIVE","新覆盖","ACTIVE",2),"ACTIVE").path("version").asInt()).isEqualTo(3);name(t,"COMMON_STATUS","旧名",0);ok(request("DELETE",path("COMMON_STATUS")+"/name?version=1",t,"restore-name-"+f.tenant(),null));assertThat(request("PUT",path("COMMON_STATUS")+"/name",t,"old-name-"+f.tenant(),Map.of("name","陈旧名称","version",0)).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(name(t,"COMMON_STATUS","新名",2).path("nameVersion").asInt()).isEqualTo(3);}
 @Test void removedCustomItemsAreNotEffectiveAndCanBeExplicitlyReenabled(){var f=fixture();String t=tenantLogin(f,"pref-admin");put(t,"SUPPLIER_TYPE","LOGISTICS","物流","LOGISTICS",0);ok(request("DELETE",path("SUPPLIER_TYPE")+"/items/LOGISTICS?version=1",t,"remove-"+f.tenant(),null));var d=get(t,"SUPPLIER_TYPE");assertThat(entry(d,"LOGISTICS")).isNull();assertThat(d.path("removedItems").size()).isOne();assertThat(d.path("removedItems").get(0).path("version").asInt()).isEqualTo(2);assertThat(request("PUT",path("SUPPLIER_TYPE")+"/items/LOGISTICS",t,"old-custom-"+f.tenant(),body("LOGISTICS","陈旧物流","LOGISTICS",0)).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(entry(put(t,"SUPPLIER_TYPE","LOGISTICS","新物流","LOGISTICS",2),"LOGISTICS").path("version").asInt()).isEqualTo(3);}
 @Test void coreValuesExtensionsPermissionsAndRealmFailClosed(){var f=fixture();String t=tenantLogin(f,"pref-admin");assertThat(request("PUT",path("COMMON_STATUS")+"/items/ACTIVE",t,"bad-core-"+f.tenant(),body("ACTIVE","伪值","OTHER",0)).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);assertThat(request("PUT",path("COMMON_STATUS")+"/items/OTHER",t,"bad-extension-"+f.tenant(),body("OTHER","扩展","OTHER",0)).getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);assertThat(request("GET",path("COMMON_STATUS"),login(true),null,null).getStatusCode().value()).isIn(401,403);assertThat(request("GET",path("COMMON_STATUS"),tenantLogin(f,"pref-reader"),null,null).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);try(var ctx=TenantContext.open(f.tenant(),f.admin())){var role=access.createRole(new AccessModels.CreateRole("DICT_VIEWER","字典只读"));access.grantRole(Long.parseLong(role.id()),new AccessModels.GrantRole(0,Set.of("system:dictionary:view","iam:menu:view"),Set.of("DICTIONARY_MANAGEMENT"),List.of()));access.createUser(new AccessModels.CreateUser("dict-reader","字典只读","Site#Initial123",Long.toString(f.first()),Set.of(role.id())));}jdbc.update("UPDATE iam_user SET force_password_change=0 WHERE tenant_id=? AND username='dict-reader'",f.tenant());String read=tenantLogin(f,"dict-reader");assertThat(get(read,"COMMON_STATUS").path("canManage").asBoolean()).isFalse();assertThat(request("PUT",path("COMMON_STATUS")+"/name",read,"denied-"+f.tenant(),Map.of("name","非法名","version",0)).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);}
 @Test void concurrentFirstOverridesHaveOneWinnerAndAuditFailureRollsBack()throws Exception{var f=fixture();String t=tenantLogin(f,"pref-admin");trigger("CREATE TRIGGER dict_fail BEFORE INSERT ON sys_audit_event FOR EACH ROW BEGIN IF NEW.action='DICTIONARY_NAME_UPDATE' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='dictionary audit test'; END IF; END");try{assertThat(request("PUT",path("COMMON_STATUS")+"/name",t,"audit-"+f.tenant(),Map.of("name","待回滚","version",0)).getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);}finally{trigger("DROP TRIGGER dict_fail");}assertThat(get(t,"COMMON_STATUS").path("nameVersion").asInt()).isZero();var gate=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{gate.await();return request("PUT",path("COMMON_STATUS")+"/name",t,"audit-"+f.tenant(),Map.of("name","并发甲","version",0)).getStatusCode().value();});var b=pool.submit(()->{gate.await();return request("PUT",path("COMMON_STATUS")+"/name",t,"other-"+f.tenant(),Map.of("name","并发乙","version",0)).getStatusCode().value();});gate.countDown();assertThat(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}finally{pool.shutdownNow();}assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM cfg_tenant_dictionary_type WHERE tenant_id=?",Integer.class,f.tenant())).isOne();}
 @Test void exactRequestReplaysButChangedBodyAndNegativeVersionReject(){var f=fixture();String t=tenantLogin(f,"pref-admin");String k="idem-"+f.tenant();var b=Map.of("name","状态本地名","version",0);var first=ok(request("PUT",path("COMMON_STATUS")+"/name",t,k,b));assertThat(ok(request("PUT",path("COMMON_STATUS")+"/name",t,k,b))).isEqualTo(first);assertThat(request("PUT",path("COMMON_STATUS")+"/name",t,k,Map.of("name","不同名","version",0)).getStatusCode()).isEqualTo(HttpStatus.CONFLICT);assertThat(request("DELETE",path("COMMON_STATUS")+"/name?version=-1",t,"negative-"+f.tenant(),null).getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);}
 @Test void simultaneousFirstItemOverridesCannotBothConsumeInheritedVersionZero()throws Exception{var f=fixture();String t=tenantLogin(f,"pref-admin");var gate=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{gate.await();return request("PUT",path("COMMON_STATUS")+"/items/ACTIVE",t,"first-a-"+f.tenant(),body("ACTIVE","甲启用","ACTIVE",0)).getStatusCode().value();});var b=pool.submit(()->{gate.await();return request("PUT",path("COMMON_STATUS")+"/items/ACTIVE",t,"first-b-"+f.tenant(),body("ACTIVE","乙启用","ACTIVE",0)).getStatusCode().value();});gate.countDown();assertThat(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}finally{pool.shutdownNow();}assertThat(entry(get(t,"COMMON_STATUS"),"ACTIVE").path("version").asInt()).isOne();}

}
